insert into game.seasons (slug, title, content)
values ('season-1', 'Last Login — Season 1: The Overlook', '{"slug":"season-1","title":"Last Login — Season 1: The Overlook","clock":{"now":"1997-10-18T21:47:00"},"computer":{"owner":"Casey Brennan","loginUser":"casey","loginTargetId":"login.casey","loginHint":"C — quit using mom’s flower + the year. anyone could guess it. — J"},"passwords":{"login.casey":{"password":"sunflower97"}},"wallpaper":"teal","homeUrl":"www.searchhound.net","maxPasswordAttempts":8,"lockoutSeconds":300,"discoveries":[{"id":"overlook-plan","title":"The overlook plan","description":"Dana believed Casey went to meet Mel at the overlook on Friday night. Mel swears no such plan was ever made."},{"id":"ghostbridge-logs","title":"GhostBridge","description":"Casey spent her last night online talking to a screen name nobody in her life recognizes — and it asked her to delete the logs."},{"id":"third-screen-name","title":"The third screen name","description":"Casey thought she was talking to Mel. Mel never sent those messages. Whoever was behind GhostBridge knew things only Mel should know.","endsDemo":true}],"buddies":[{"screenname":"MelWave81","alias":"mel","group":"Buddies","status":"away","awayMessage":"not here. leave one.","conversationId":"im.melwave81"},{"screenname":"beccs8r","alias":"becca","group":"Buddies","status":"online","conversationId":"im.beccs8r"},{"screenname":"DHartnell","alias":"dana","group":"Buddies","status":"online"},{"screenname":"jjbrennan","alias":"jesse (bro)","group":"Family","status":"offline"},{"screenname":"GhostBridge","group":"Buddies","status":"offline","conversationId":"im.ghostbridge","requires":{"discovery":"overlook-plan"}}],"items":[{"id":"folder.c","kind":"folder","name":"Casey (C:)","icon":"drive","meta":{"path":"C:\\","desktop":{"x":24,"y":24}}},{"id":"folder.my-documents","kind":"folder","name":"My Documents","icon":"folder-docs","parentId":"folder.c","meta":{"path":"C:\\My Documents","modifiedAt":"1997-10-10","desktop":{"x":24,"y":120}}},{"id":"folder.pictures","kind":"folder","name":"Pictures","icon":"folder-pics","parentId":"folder.c","meta":{"path":"C:\\Pictures","modifiedAt":"1997-09-28","desktop":{"x":24,"y":216}}},{"id":"folder.downloads","kind":"folder","name":"Downloads","icon":"folder","parentId":"folder.c","meta":{"path":"C:\\Downloads","modifiedAt":"1997-10-06"}},{"id":"folder.programs","kind":"folder","name":"Program Files","icon":"folder","parentId":"folder.c","meta":{"path":"C:\\Program Files","modifiedAt":"1997-08-14"}},{"id":"folder.school","kind":"folder","name":"School","icon":"folder","parentId":"folder.my-documents","meta":{"path":"C:\\My Documents\\School","modifiedAt":"1997-10-08"}},{"id":"folder.personal","kind":"folder","name":"personal stuff","icon":"folder","parentId":"folder.my-documents","meta":{"path":"C:\\My Documents\\personal stuff","modifiedAt":"1997-10-10"}},{"id":"folder.writing","kind":"folder","name":"Writing!!","icon":"folder","parentId":"folder.my-documents","meta":{"path":"C:\\My Documents\\Writing!!","modifiedAt":"1997-09-30"}},{"id":"file.civilwar-report","kind":"document","name":"report_civilwar_FINAL2.txt","icon":"doc","parentId":"folder.school","meta":{"createdAt":"1997-10-02","modifiedAt":"1997-10-08","sizeKb":6},"body":{"text":"THE HOMEFRONT ECONOMY, 1861-1865\nCasey Brennan, Per. 3, Mr. Whitfield\n\nThe war changed daily life for ordinary families in ways textbooks\nmostly skip. Prices of coffee and cloth rose sharply. Women ran farms\nand shops. Letters took weeks to arrive, if they arrived at all.\n\n(NOTE TO SELF: whitfield wants 3 pages. this is 1.5. pad the\nconclusion. do NOT forget the bibliography this time)\n\nSources so far:\n- library encyclopedia vol 4\n- that PBS-looking documentary grandpa taped\n- searchhound \"civil war economy\" (mostly junk)"}},{"id":"file.algebra","kind":"document","name":"algebra_hw_oct6.txt","icon":"doc","parentId":"folder.school","meta":{"createdAt":"1997-10-06","modifiedAt":"1997-10-06","sizeKb":1},"body":{"text":"p.114 #1-19 odd\n3) x = 7\n5) x = -2\n7) x = 4/3 ?? check w/ mel\n9) skipped, ask in class\n11) x = 11\n13) no idea. NO idea.\n\nquiz friday (the 10th) — STUDY THURS"}},{"id":"file.english-journal","kind":"document","name":"english journal wk4.txt","icon":"doc","parentId":"folder.school","meta":{"createdAt":"1997-09-29","modifiedAt":"1997-09-29","sizeKb":2},"body":{"text":"English 10 — journal, week 4\nPrompt: \"Describe a place that matters to you.\"\n\nThe reservoir in summer, I guess. Everyone goes to the swim beach side\nbut if you walk the fire road past the pump house there''s a spot where\nthe pines open up and you can see the whole valley. Dad used to take us\nup there before he moved. It''s quieter than anywhere.\n\n(ms. okafor said \"lovely detail\" on my last one so I''m keeping the\nnature thing going. easy A.)"}},{"id":"file.lists","kind":"document","name":"lists.txt","icon":"doc","parentId":"folder.personal","meta":{"createdAt":"1997-08-19","modifiedAt":"1997-10-04","sizeKb":1},"body":{"text":"MIXTAPE FOR DANA (side A)\n1. solar flare - static heart\n2. the plimsouls?? ask jesse\n3. that song from the radio tues (find out name)\n4. velvet june - anywhere but here\n5. solar flare - carousel\n\nTHINGS I NEED\n- new batteries for the discman\n- blank tapes (maxell, NOT the cheap ones)\n- $$ for the fair. ask mom. beg mom.\n\nPEOPLE WHO OWE ME\n- becca $4 (movie)\n- jesse infinite dollars (emotional damages)"}},{"id":"file.songs","kind":"document","name":"songs i wrote (private).txt","icon":"doc","parentId":"folder.personal","meta":{"createdAt":"1997-07-11","modifiedAt":"1997-09-21","sizeKb":2},"body":{"text":"** if anyone reads this i will literally die **\n\n\"COIN ON THE TRACKS\"\nwe put a coin on the tracks in june\nflattened silver, cheap little moon\nyou said keep it, i kept it too\nsome things stay even when people move\n\n(chorus needs work. everything needs work.)\n\n\"UNTITLED 3\"\nthe porch light stays on all night now\nmoths keep faith better than people do\n\n(too sad? too sad.)"}},{"id":"file.oct-pages","kind":"document","name":"oct_pages.txt","icon":"doc","parentId":"folder.personal","meta":{"createdAt":"1997-10-01","modifiedAt":"1997-10-10","sizeKb":3},"requires":{"discovery":"ghostbridge-logs"},"onOpen":{"discover":["third-screen-name"]},"body":{"text":"oct 1 — mom took double shifts again. house is SO quiet. jesse called\nfrom state, talked for an hour about his roommate''s ferret. a FERRET.\n\noct 5 — fair with dana + becca. won a goldfish, named him Agent. he is\nalready looking unwell. godspeed Agent.\n\noct 9 — ok so. someone new messaged me two nights ago. wouldn''t say who\nthey were at first, just \"you know me.\" i thought it was becca messing\naround but they knew stuff becca doesn''t know. then last night they\nsaid it. they knew about the bracelet. THE BRACELET. only mel knows\nabout the bracelet. only mel on the ENTIRE EARTH.\n\nso it has to be mel, right? new screen name, being weird, whatever.\nthat''s a mel thing to do.\n\noct 10 — m wants to meet at the overlook tonight. 10pm. \"come alone,\ntell no one, delete the logs.\" which is dramatic even for mel.\n\nbut here''s the thing i keep not writing down. mel types \"hehe.\" mel\ncan''t spell definitely. mel says goodnight like a normal person.\nGhostBridge types like... i don''t know. like someone doing an\nimpression of a person.\n\nit knew about the bracelet. so it HAS to be mel.\n\nunless somehow it isn''t.\n\ngoing anyway. if this is mel i''m going to kill her."}},{"id":"file.lighthouse","kind":"document","name":"story - the lighthouse keeper (unfinished).txt","icon":"doc","parentId":"folder.writing","meta":{"createdAt":"1997-09-14","modifiedAt":"1997-09-30","sizeKb":4},"body":{"text":"THE LIGHTHOUSE KEEPER (working title)\nby C. Brennan\n\nMarta had kept the light for eleven years and in eleven years she had\nlearned that the sea does not take people. People give themselves to\nit, a little at a time, in ways nobody notices until the giving is\ndone.\n\nThe boy arrived on a Tuesday, soaked through, holding a shoebox.\n\"There''s a bird in here,\" he said. \"It''s not doing so hot.\"\n\n[chapter 2 goes here. marta fixes the bird. the bird is NOT a metaphor\nmrs okafor, sometimes a bird is a bird]"}},{"id":"file.tourdates","kind":"document","name":"solarflare_tourdates.txt","icon":"doc","parentId":"folder.downloads","meta":{"createdAt":"1997-10-06","modifiedAt":"1997-10-06","sizeKb":1},"body":{"text":"SOLAR FLARE — \"STATIC HEART\" TOUR — FALL 97\n(from the fan club page. saved so I stop losing it)\n\nOCT 24 - PORTVALE, CIVIC HALL\nOCT 26 - RIVERTON, THE ARMORY  <-- 2 HRS AWAY. POSSIBLE??\nNOV 01 - CASCADE CITY, FAIRGROUNDS\nNOV 03 - MERIDIAN, STATE THEATER\n\nall ages except meridian. tickets $12 + service charge (robbery)"}},{"id":"file.chainletter-dl","kind":"document","name":"GOOD_LUCK_ANGEL.txt","icon":"doc","parentId":"folder.downloads","meta":{"createdAt":"1997-09-25","modifiedAt":"1997-09-25","sizeKb":2},"body":{"text":"THIS IS THE GOOD LUCK ANGEL !!! (>o<)\n\nSend her to 10 friends within 24 HOURS and something WONDERFUL will\nhappen to you by the weekend. Marcy T. of Ohio deleted this message\nand her modem was struck by LIGHTNING. Do not risk it!!!\n\n(becca sent me this. i am keeping it purely as evidence against her)"}},{"id":"file.readme-first","kind":"document","name":"readme 1st.txt","icon":"doc","parentId":"folder.c","meta":{"createdAt":"1997-08-30","modifiedAt":"1997-08-30","sizeKb":1,"desktop":{"x":312,"y":24}},"body":{"text":"casey —\nfixed your sound card AGAIN. you''re welcome AGAIN.\ndon''t install junk off the web. if the modem does the screechy thing,\nunplug it, count to ten, act natural.\nalso you left your discman in my car. it''s on the fridge.\n— jesse\n\nps. change your password. i guessed it in one try. ONE."}},{"id":"file.datebook-1997","kind":"document","name":"datebook.dat","icon":"doc","meta":{"createdAt":"1997-01-04","modifiedAt":"1997-10-09","sizeKb":2},"body":{"text":"1997-09-19: band practice (jesse''s garage. bring earplugs)\n1997-09-26: english journal due\n1997-10-03: sleepover @ mel''s\n1997-10-04: FAIR!!! w/ d + b\n1997-10-09: STUDY. quiz tmrw. actually study\n1997-10-10: algebra quiz\n1997-10-10: ★ 10pm\n1997-10-14: dana bday ideas?? (NOT a mixtape again. ok maybe a mixtape)\n1997-10-21: picture retakes (fix bangs FIRST this time)\n1997-10-25: homecoming - find shoes\n1997-10-26: SOLAR FLARE RIVERTON?? beg mom. beg harder\n1997-11-27: thanksgiving @ aunt patty''s (ron. turkey. fire dept on standby)"}},{"id":"photo.fair","kind":"photo","name":"fair_ferris_aug97.gif","icon":"photo","parentId":"folder.pictures","meta":{"createdAt":"1997-08-23","sizeKb":84,"caption":"county fair w/ dana + becca. becca lost her churro on this ride.","photoSrc":"/photos/fair_ferris.svg"}},{"id":"photo.lockers","kind":"photo","name":"me_and_dana_lockers.gif","icon":"photo","parentId":"folder.pictures","meta":{"createdAt":"1997-09-05","sizeKb":71,"caption":"first week of sophomore year. dana decorated my locker. it is SO much.","photoSrc":"/photos/lockers.svg"}},{"id":"photo.buster","kind":"photo","name":"buster_box.gif","icon":"photo","parentId":"folder.pictures","meta":{"createdAt":"1997-07-30","sizeKb":66,"caption":"buster claims another box. the box was for him actually.","photoSrc":"/photos/buster.svg"}},{"id":"photo.reservoir","kind":"photo","name":"reservoir_last_swim.gif","icon":"photo","parentId":"folder.pictures","meta":{"createdAt":"1997-08-31","sizeKb":90,"caption":"last swim of summer. water was FREEZING. worth it.","photoSrc":"/photos/reservoir.svg"}},{"id":"photo.garage","kind":"photo","name":"jesses_band_garage.gif","icon":"photo","parentId":"folder.pictures","meta":{"createdAt":"1997-06-14","sizeKb":77,"caption":"jesse''s band practicing. they are not good. do not tell jesse.","photoSrc":"/photos/garage.svg"}},{"id":"photo.sweet16","kind":"photo","name":"sweet16_cake.gif","icon":"photo","parentId":"folder.pictures","meta":{"createdAt":"1997-04-12","sizeKb":82,"caption":"mom made the cake herself. it leaned. we loved it.","photoSrc":"/photos/sweet16.svg"}},{"id":"photo.sunflowers","kind":"photo","name":"moms_sunflowers.gif","icon":"photo","parentId":"folder.pictures","meta":{"createdAt":"1997-08-10","sizeKb":74,"caption":"mom''s sunflowers got taller than the fence this year. she''s unbearable about it.","photoSrc":"/photos/sunflowers.svg"}},{"id":"mailbox.inbox","kind":"mailbox","name":"Inbox","icon":"mailbox"},{"id":"mailbox.sent","kind":"mailbox","name":"Sent","icon":"mailbox"},{"id":"mailbox.deleted","kind":"mailbox","name":"Deleted","icon":"mailbox-trash"},{"id":"email.dana.please-write-back","kind":"email","name":"please write back","icon":"mail","parentId":"mailbox.inbox","meta":{"from":"Dana Hartnell <dhartnell@westwind.net>","to":"casey_b@westwind.net","date":"1997-10-11T16:22:00"},"onOpen":{"discover":["overlook-plan"]},"body":{"text":"casey.\n\ni don''t even know why i''m writing this. maybe you''ll dial in from\nsomewhere and see it. maybe your mom will. i don''t know.\n\nthe police talked to me AGAIN today. i told them what i told them\nbefore. you said you were meeting mel at the overlook friday night.\nthat''s what you told me at lunch. \"meeting mel, don''t wait up, it''s a\nwhole thing.\"\n\nbut casey. mel says there was no plan. she wasn''t even home friday,\nshe was at her cousin''s in portvale, her mom confirmed it. she found\nout you said that and she cried in the bathroom for the whole of\nthird period.\n\nso either mel is lying, which — it''s MEL. or you lied to me. and you\ndon''t lie to me. you never lie to me.\n\nwho were you actually going to meet?\n\nplease just write back. i''m not even mad. i just want you to write\nback.\n\n- d"}},{"id":"email.dana.answer-me","kind":"email","name":"(no subject)","icon":"mail","parentId":"mailbox.inbox","meta":{"from":"Dana Hartnell <dhartnell@westwind.net>","to":"casey_b@westwind.net","date":"1997-10-14T23:05:00"},"body":{"text":"it''s late and your porch light is on. i can see it from my window.\nyour mom leaves it on for you.\n\nok.\n\nthat''s all. that''s the whole email.\n\n- d"}},{"id":"email.mom.leftovers","kind":"email","name":"dinner","icon":"mail","parentId":"mailbox.inbox","meta":{"from":"Linda Brennan <lbrennan@westwind.net>","to":"casey_b@westwind.net","date":"1997-10-09T17:41:00"},"body":{"text":"Casey - working the late shift again tonight, there''s leftover\ncasserole in the fridge, the GOOD tupperware not the mystery one in\nthe back. Feed Buster, do your homework, don''t stay on that computer\nall night, the phone bill was $$$ last month.\n\nLove you. Mom\n\nP.S. Aunt Patty says you never answered her email about Thanksgiving.\nAnswer your aunt."}},{"id":"email.school.newsletter","kind":"email","name":"MGH FALCON FLYER - Week of Oct 6","icon":"mail","parentId":"mailbox.inbox","meta":{"from":"Maple Glen High School <office@mapleglen.k12.net>","to":"students@mapleglen.k12.net","date":"1997-10-08T09:00:00"},"body":{"text":"THE FALCON FLYER — Maple Glen High School — Week of October 6, 1997\n\n* FALL SPORTS: Varsity soccer defeats Riverton 2-1. JV volleyball\n  hosts Portvale Thursday.\n* PICTURE RETAKES are October 21. Forms in the front office.\n* The HOMECOMING DANCE is October 25 in the main gym. Theme:\n  \"A Night Under the Stars.\" Tickets $5 at lunch.\n* REMINDER: The fire road behind the reservoir is CLOSED to students.\n  This is county property. Violators will be cited.\n* Chess club needs members. Seriously. Anyone. Please."}},{"id":"email.becca.chain","kind":"email","name":"FW: FW: FW: THE GOOD LUCK ANGEL!!!","icon":"mail","parentId":"mailbox.inbox","meta":{"from":"becca t <beccs8r@westwind.net>","to":"casey_b@westwind.net","date":"1997-10-07T20:14:00"},"body":{"text":">>> SEND TO 10 FRIENDS IN 24 HOURS OR ELSE <<<\n\nok i KNOW you don''t believe in these but marcy t. of ohio''s modem\ngot struck by LIGHTNING casey. LIGHTNING. i''m not taking chances\nand neither should you.\n\n(also are we still on for the fair pics? my mom finally got the film\ndeveloped. you look cute, i look like i''m being arrested.)\n\nxoxo becca"}},{"id":"email.fanclub.digest","kind":"email","name":"SOLAR FLARE FAN CIRCLE - Digest #44","icon":"mail","parentId":"mailbox.inbox","meta":{"from":"Solar Flare Fan Circle <circle@solarflareband.net>","to":"circle@solarflareband.net","date":"1997-10-06T06:30:00"},"body":{"text":"SOLAR FLARE FAN CIRCLE — DIGEST #44\n\n1) TOUR DATES CONFIRMED (see the website for the full list!)\n2) StaticHeartGrrl asks: is the hidden track on side B real or a\n   pressing error? (17 replies. it''s getting heated.)\n3) Trade board: I have a RIVERTON 96 bootleg tape, looking for the\n   acoustic radio session. No rippers this time please.\n\nTo unsubscribe, reply UNSUBSCRIBE. (This has never once worked.)"}},{"id":"email.aunt-patty","kind":"email","name":"Thanksgiving??","icon":"mail","parentId":"mailbox.inbox","meta":{"from":"Patricia Kowalski <pkowalski@westwind.net>","to":"casey_b@westwind.net","date":"1997-10-05T11:12:00"},"body":{"text":"Hi sweetheart! It''s your Aunt Patty! I am typing this on Ron''s new\ncomputer so forgive me if it comes out strange. Are you and your mom\nand Jesse coming for Thanksgiving? Ron is deep-frying the turkey this\nyear which the fire department has opinions about. Let me know!! Love,\nAunt Patty\n\nP.S. how do I make the letters bigger. Ron doesn''t know either."}},{"id":"email.westwind.notice","kind":"email","name":"WestWind Mail: Your mailbox is 80% full","icon":"mail","parentId":"mailbox.inbox","meta":{"from":"WestWind Online <postmaster@westwind.net>","to":"casey_b@westwind.net","date":"1997-10-03T04:00:00"},"body":{"text":"Dear WestWind Member,\n\nYour mailbox (casey_b) is at 80% of its 2 MB storage limit. To avoid\nmissed messages, please delete old mail or upgrade to WestWind GOLD\nfor just $4.95/month and enjoy a spacious 10 MB.\n\nWestWind Online — \"Your Window to the World Wide Web\"\nMember Services | Dial-up Support: 1-800-555-0134"}},{"id":"email.sent.dana-homework","kind":"email","name":"re: did you do the algebra","icon":"mail","parentId":"mailbox.sent","meta":{"from":"casey_b@westwind.net","to":"Dana Hartnell <dhartnell@westwind.net>","date":"1997-10-09T21:58:00"},"body":{"text":"> did you do the algebra or are we both doomed\n\ndid most of it. #13 is a war crime. copy mine at lunch.\n\ncan''t talk tonight - busy online. tell you about it later. maybe.\nit''s kind of a weird thing.\n\n- c"}},{"id":"email.sent.mom-cat","kind":"email","name":"re: dinner","icon":"mail","parentId":"mailbox.sent","meta":{"from":"casey_b@westwind.net","to":"Linda Brennan <lbrennan@westwind.net>","date":"1997-10-09T18:03:00"},"body":{"text":"yes i fed buster. yes the good tupperware. yes i''ll answer aunt patty.\nthe phone bill is jesse''s fault historically and spiritually.\n\nlove you, bye, i''m fine"}},{"id":"email.deleted.coupon","kind":"email","name":"SAVE BIG at Compu-Barn! October Blowout","icon":"mail","parentId":"mailbox.deleted","meta":{"from":"Compu-Barn Superstore <deals@compubarn.net>","to":"casey_b@westwind.net","date":"1997-10-02T12:00:00"},"body":{"text":"COMPU-BARN OCTOBER BLOWOUT! 56K modems from $89! Blank 3.5\" disks\n10-pack: $4.99! Ink cartridges (ask an associate)! Compu-Barn: We''re\nPractically Giving It Away (Legal: we are not giving it away.)"}},{"id":"im.melwave81","kind":"im_conversation","name":"MelWave81","icon":"im","meta":{"screenname":"MelWave81","alias":"mel","logDate":"1997-10-08"},"body":{"messages":[{"from":"MelWave81","at":"8:12 PM","text":"did u start the civil war thing"},{"from":"SunflwrC81","at":"8:12 PM","text":"define started"},{"from":"MelWave81","at":"8:13 PM","text":"hehe. so no"},{"from":"SunflwrC81","at":"8:13 PM","text":"i have a TITLE. titles are half the battle"},{"from":"MelWave81","at":"8:14 PM","text":"the battle is definately the other half"},{"from":"SunflwrC81","at":"8:14 PM","text":"*definitely"},{"from":"MelWave81","at":"8:14 PM","text":"i will block u"},{"from":"SunflwrC81","at":"8:16 PM","text":"becca wants to do a thing at the reservoir sat. u in?"},{"from":"MelWave81","at":"8:17 PM","text":"cant. cousins in portvale this wkend. moms making me"},{"from":"SunflwrC81","at":"8:17 PM","text":"boooo"},{"from":"MelWave81","at":"8:19 PM","text":"hey random but. u still have it right"},{"from":"SunflwrC81","at":"8:19 PM","text":"have what"},{"from":"MelWave81","at":"8:19 PM","text":"u KNOW what. bracelet"},{"from":"SunflwrC81","at":"8:20 PM","text":"obviously. its in the box in the box in the box"},{"from":"MelWave81","at":"8:20 PM","text":"good. ok. that stays us-only FOREVER. swear again"},{"from":"SunflwrC81","at":"8:20 PM","text":"i swear AGAIN. u weirdo. nobody knows. nobody will ever know"},{"from":"MelWave81","at":"8:21 PM","text":"ok hehe. gnight casey"},{"from":"SunflwrC81","at":"8:21 PM","text":"night mel"}]}},{"id":"im.beccs8r","kind":"im_conversation","name":"beccs8r","icon":"im","meta":{"screenname":"beccs8r","alias":"becca","logDate":"1997-10-09"},"body":{"messages":[{"from":"beccs8r","at":"7:02 PM","text":"RESERVOIR SATURDAY. spread the word. my brother can drive"},{"from":"SunflwrC81","at":"7:04 PM","text":"ur brother drives like the car owes him money"},{"from":"beccs8r","at":"7:04 PM","text":"and yet. free ride"},{"from":"beccs8r","at":"7:05 PM","text":"did u get my angel email. did u send it to 10 ppl"},{"from":"SunflwrC81","at":"7:05 PM","text":"i deleted it and i feel STRONGER for it"},{"from":"beccs8r","at":"7:06 PM","text":"marcy t of ohio casey. LIGHTNING"},{"from":"SunflwrC81","at":"7:08 PM","text":"gtg. someone msgd me"},{"from":"beccs8r","at":"7:08 PM","text":"oooooo who"},{"from":"SunflwrC81","at":"7:09 PM","text":"nobody. tell u later"},{"from":"beccs8r","at":"7:09 PM","text":"RUDE. fine. sat!!"}]}},{"id":"im.ghostbridge","kind":"im_conversation","name":"GhostBridge","icon":"im","meta":{"screenname":"GhostBridge","logDate":"1997-10-10"},"requires":{"discovery":"overlook-plan"},"onOpen":{"discover":["ghostbridge-logs"]},"body":{"messages":[{"from":"GhostBridge","at":"9:31 PM","text":"are you alone"},{"from":"SunflwrC81","at":"9:31 PM","text":"yes?? mom works fridays. u know that"},{"from":"GhostBridge","at":"9:32 PM","text":"good. tonight then. the overlook. 10 pm."},{"from":"SunflwrC81","at":"9:32 PM","text":"ok this has gone on long enough. mel is this you"},{"from":"SunflwrC81","at":"9:32 PM","text":"why the new name. whats wrong w/ ur normal one"},{"from":"GhostBridge","at":"9:33 PM","text":"you already know who i am."},{"from":"SunflwrC81","at":"9:33 PM","text":"say something only mel would know then"},{"from":"GhostBridge","at":"9:34 PM","text":"june. the tracks. the coin you flattened."},{"from":"GhostBridge","at":"9:34 PM","text":"the bracelet in the box in the box in the box."},{"from":"SunflwrC81","at":"9:35 PM","text":"ok. ok fine its you. u had me going honestly"},{"from":"SunflwrC81","at":"9:35 PM","text":"but ur supposed to be in portvale?? did ur mom cancel"},{"from":"GhostBridge","at":"9:36 PM","text":"come alone. tell no one. not dana."},{"from":"SunflwrC81","at":"9:36 PM","text":"ur being so dramatic tonight lol"},{"from":"GhostBridge","at":"9:37 PM","text":"and delete these logs after. all of them. promise me."},{"from":"SunflwrC81","at":"9:37 PM","text":"FINE i promise. this better be good mel"},{"from":"GhostBridge","at":"9:38 PM","text":"it will all make sense at the overlook."},{"from":"GhostBridge","at":"9:38 PM","text":"goodnight casey"},{"from":"SunflwrC81","at":"9:39 PM","text":"ok NOW i know something is up. u never say goodnight like that"},{"from":"SunflwrC81","at":"9:39 PM","text":"mel?"},{"from":"SunflwrC81","at":"9:41 PM","text":"hello??"}]}},{"id":"folder.recycle","kind":"folder","name":"Recycle Bin","icon":"trash"},{"id":"trash.essay-draft","kind":"trash_item","name":"english_essay_draft1.txt","icon":"doc","parentId":"folder.recycle","meta":{"deletedAt":"1997-10-08",